#!/usr/bin/env Rscript
args<-commandArgs(trailingOnly=TRUE);if(length(args)!=1L)stop("Provide project.yaml",call.=FALSE)
all<-commandArgs(trailingOnly=FALSE);self<-normalizePath(sub("^--file=","",grep("^--file=",all,value=TRUE)[[1]]),winslash="/");root<-normalizePath(file.path(dirname(self),"../.."),winslash="/")
`%||%`<-function(left,right)if(is.null(left)||!length(left))right else left;source(file.path(root,"app/shiny/R/project_discovery.R"));source(file.path(root,"app/shiny/R/fitness_result_state.R"));project<-read_project_summary(args[[1]],root);results<-discover_fitness_results(project);stopifnot(length(results)>0L);result<-choose_latest_fitness_result(results);data<-fitness_result_data(result);counts<-fitness_call_counts(data);column<-fitness_call_column(data);stopifnot(nrow(data)>0L,sum(counts)==nrow(data),nzchar(column),nrow(filter_fitness_results(data,as.character(data[[column]][[1]]),""))>0L,nrow(filter_fitness_results(data,"All",as.character(data$feature_id[[1]])))>0L,!any(grepl(project$project_root,unlist(fitness_result_table_data(data)),fixed=TRUE)),file.exists(result$table),file.exists(result$comparison_summary))
ui<-paste(readLines(file.path(root,"app/shiny/R/ui_fitness.R"),warn=FALSE),collapse="\n");stopifnot(grepl("Fitness call distribution",ui),grepl("Effect size versus z-score",ui),!grepl("Volcano",ui,ignore.case=TRUE),!grepl("p.value|p_value|adjusted",ui,ignore.case=TRUE),grepl("tags\\$details\\(class=\"ytab-technical-details\"",ui))
missing<-fitness_result_table_data(data.frame(feature_id="x"));stopifnot(nrow(missing)==1L);cat("PASS\n")
